const response = await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://127.0.0.1:47123/code-404',
  ignoreHttpStatusErrors: true,
  returnFullResponse: true,
});
return [{ json: { statusCode: response.statusCode, statusMessage: response.statusMessage, body: response.body } }];

await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://127.0.0.1:47123/code-fails',
});
return [{ json: { threw: false } }];
